package fft

// dct4FusedRoute is true where the fused DCT-IV kernels beat the pooled path
// (Apple M4 Max, 64: 88 ns to 44 ns, go-fft/fft#132); amd64 keeps its AVX2 kernels.
const dct4FusedRoute = true

// dct4PairRoute: the NEON pair kernels (64 and 128) run on every arm64 CPU.
func dct4PairRoute(n int) bool { return dct4FusedLen(n) }

// The NEON pair kernels (dct4_64_arm64.s, dct4_128_arm64.s, generated by
// internal/gendct4): two DCT-IV in the two lanes of every vector register, so each
// instruction does both transforms. They read all inputs of both streams before the
// first store; dst0 may alias src0 and dst1 may alias src1 but no other overlap is
// allowed (runPair checks). They spill to their own stack frame.

//go:noescape
func dct4n64PairF64(dst0, dst1, src0, src1 *float64, w *dct4n64VTab)

//go:noescape
func dct4n64PairF64S(dst0, dst1, src0, src1 *float64, w *dct4n64VTab, f float64)

//go:noescape
func dct4n64PairF32(dst0, dst1, src0, src1 *float32, w *dct4n64VTab)

//go:noescape
func dct4n64PairF32S(dst0, dst1, src0, src1 *float32, w *dct4n64VTab, f float64)

//go:noescape
func dct4n128PairF64(dst0, dst1, src0, src1 *float64, w *dct4n128VTab)

//go:noescape
func dct4n128PairF64S(dst0, dst1, src0, src1 *float64, w *dct4n128VTab, f float64)

//go:noescape
func dct4n128PairF32(dst0, dst1, src0, src1 *float32, w *dct4n128VTab)

//go:noescape
func dct4n128PairF32S(dst0, dst1, src0, src1 *float32, w *dct4n128VTab, f float64)

// dct4Pair runs the pair kernel of length n (64 or 128), scaled by f unless f is 1.
func dct4Pair(n int, dst0, dst1, src0, src1 []float64, f float64) {
	switch {
	case n == 64 && f != 1:
		dct4n64PairF64S(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n64V, f)
	case n == 64:
		dct4n64PairF64(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n64V)
	case f != 1:
		dct4n128PairF64S(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n128V, f)
	default:
		dct4n128PairF64(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n128V)
	}
}

// dct4PairMixed is dct4Pair on float32 data.
func dct4PairMixed(n int, dst0, dst1, src0, src1 []float32, f float64) {
	switch {
	case n == 64 && f != 1:
		dct4n64PairF32S(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n64V, f)
	case n == 64:
		dct4n64PairF32(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n64V)
	case f != 1:
		dct4n128PairF32S(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n128V, f)
	default:
		dct4n128PairF32(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n128V)
	}
}
